function dydt = sdof_system(t, y, m, c, k, F0, omega)
    % Differential equations for SDOF system under dynamic load
    % y(1) = displacement, y(2) = velocity
    dydt = zeros(2, 1);
    dydt(1) = y(2);
    dydt(2) = (F0 * sin(omega * t) - c * y(2) - k * y(1)) / m;
end

