% 悬臂梁（建筑物）的自由衰减振动过程模拟，考虑前五阶振型，并添加选择振型功能

% 参数设置
L = 100;            % 楼的高度 (m)
width = 2;          % 楼的宽度 (m)
amplitude = 2;      % 初始位移幅度 (m)
zeta = 0.051;       % 阻尼比
omega_n = 2 * pi / 10;  % 自然频率 (rad/s)，假设周期为10秒
T = 30;             % 模拟时间 (s)
fps = 30;           % 帧率 (frames per second)
num_frames = T * fps; % 总帧数

% 定义时间向量
t = linspace(0, T, num_frames);  % 时间向量

% 用户选择振型 (1-5)
mode_choice = 4;

% 定义振型特征值（前五阶）
beta = [1.87510407, 4.69409113, 7.85475744, 10.99560784, 14.13716549];  % 前五阶悬臂梁特征值 (无量纲)

% 根据选择的振型设置振型函数
if mode_choice >= 1 && mode_choice <= 5
    beta_n = beta(mode_choice);
else
    disp('无效选择，默认使用第一振型');
    beta_n = beta(1);
end

% 定义自由衰减运动位移公式：x(t) = A * exp(-zeta*omega_n*t) * cos(omega_d * t)
omega_d = omega_n * sqrt(1 - zeta^2);  % 阻尼后的频率 (rad/s)
x_t = @(t) amplitude * exp(-zeta * omega_n * t) .* cos(omega_d * t);  % 计算顶端位移

% 定义选择的振型函数
phi_n = @(y) cosh(beta_n * y / L) - cos(beta_n * y / L) - ...
    ((cosh(beta_n) + cos(beta_n)) / (sinh(beta_n) + sin(beta_n))) * (sinh(beta_n * y / L) - sin(beta_n * y / L));

% 高度分布
y = linspace(0, L, 50);  % 从底部到顶部的高度划分成50段

% 选择顶端和中间位置的高度
y_top = L;              % 顶端高度
y_mid = L * 0.5;        % 中间高度

% 初始化存储顶端和中间位置的位移值
top_displacement_history = zeros(1, num_frames);
mid_displacement_history = zeros(1, num_frames);

% 动画绘制
figure;
for frame = 1:num_frames
    % 当前时间
    t_now = t(frame);
    
    % 计算当前时间的顶端位移
    top_displacement = x_t(t_now);
    
    % 计算不同高度处的位移，使用选择的振型进行缩放
    displacements = top_displacement * phi_n(y);
    
    % 计算顶端和中间位置的位移
    top_disp = top_displacement * phi_n(y_top);
    mid_disp = top_displacement * phi_n(y_mid);
    
    % 存储位移历史
    top_displacement_history(frame) = top_disp;
    mid_displacement_history(frame) = mid_disp;
    
    % 建筑物左侧和右侧的坐标（根据当前位移情况）
    x_left = -width / 2 + displacements;  % 左侧的位移
    x_right = width / 2 + displacements;  % 右侧的位移
    
    % 清除之前的图像
    clf;
    
    % 子图 1：动态展示建筑物的振动状态
    subplot(2, 2, [1 3]);
    fill([x_left, fliplr(x_right)], [y, fliplr(y)], 'b');
    hold on;
    % 标出顶端和中间位置
    plot(top_disp, y_top, 'ro', 'MarkerSize', 8, 'LineWidth', 2);  % 标出顶端
    plot(mid_disp, y_mid, 'go', 'MarkerSize', 8, 'LineWidth', 2);  % 标出中间位置
    hold off;
    axis([-10 10 0 L + 10]);  % 设置X轴为[-10, 10]，Y轴为[0, L]
    xlabel('位移 (m)');
    ylabel('高度 (m)');
    title(sprintf('自由衰减振动，第 %d 阶振型 (t = %.2f 秒)', mode_choice, t_now));
    grid on;
    
    % 子图 2：顶端位移随时间变化
    subplot(2, 2, 2);
    plot(t(1:frame), top_displacement_history(1:frame), 'r', 'LineWidth', 1.5);
    xlabel('时间 (s)');
    ylabel('顶端位移 (m)');
    title('顶端位移随时间变化');
    grid on;
    xlim([0, T]);
    ylim([-amplitude - 2, amplitude + 2]);
    
    % 子图 3：中间位置位移随时间变化
    subplot(2, 2, 4);
    plot(t(1:frame), mid_displacement_history(1:frame), 'g', 'LineWidth', 1.5);
    xlabel('时间 (s)');
    ylabel('中间位移 (m)');
    title('中间位移随时间变化');
    grid on;
    xlim([0, T]);
    ylim([-amplitude - 2, amplitude + 2]);
    
    % 暂停以创建动画效果
    pause(1/fps);
end



% 悬臂梁的前三阶振型动态响应动画（分别绘制，颠倒 x 和 y 轴）

% 参数定义
L = 10;           % 梁的长度 (m)
x = linspace(0, L, 1000);  % 沿梁的长度分布 (m)
T = 10;           % 动画持续时间 (秒)
fps = 30;         % 帧率 (frames per second)
num_frames = T * fps; % 总帧数

% 悬臂梁的前三阶特征值 (beta_n) 和固有频率 (无量纲)
beta = [1.87510407, 4.69409113, 7.85475744];  % 悬臂梁前三阶特征值
frequencies = [3.52, 22.03, 61.70];  % 对应的前三阶固有频率 (Hz) 估计值，参考悬臂梁理论

% 定义振型函数
vibration_mode = @(beta_n, x, L) (cosh(beta_n * x / L) - cos(beta_n * x / L)) - ...
    ((cosh(beta_n) + cos(beta_n)) / (sinh(beta_n) + sin(beta_n))) * (sinh(beta_n * x / L) - sin(beta_n * x / L));

% 计算前三阶振型
mode1 = vibration_mode(beta(1), x, L);
mode2 = vibration_mode(beta(2), x, L);
mode3 = vibration_mode(beta(3), x, L);

% 设置振幅和振动频率
amplitude = [0.1, 0.05, 0.02];  % 振动的幅度
omega = 2 * pi * frequencies;  % 转换为角频率 (rad/s)

% 创建第一阶振型动画
figure;
for frame = 1:num_frames
    t = (frame - 1) / fps;  % 当前时间
    
    % 计算第一阶振型的动态响应（正弦函数模拟振动）
    y1 = amplitude(1) * mode1 * sin(omega(1) * t);  % 第一阶振型
    
    % 绘制第一阶振型 (将 y1 放在 x 轴，x 放在 y 轴)
    plot(y1, x, 'LineWidth', 2);
    axis([-0.2 0.2 0 L]);  % 设置X轴和Y轴范围
    xlabel('位移 (m)');
    ylabel('梁的长度 (m)');
    title(sprintf('悬臂梁第一阶振型 (t = %.2f 秒)', t));
    grid on;
    
    % 暂停以创建动画效果
    pause(1/fps);
end

% 创建第二阶振型动画
figure;
for frame = 1:num_frames
    t = (frame - 1) / fps;  % 当前时间
    
    % 计算第二阶振型的动态响应
