    pause(1/fps);
end


% 悬臂梁的动态响应动画，添加时变塔顶和中部位置的位移展示

% 参数定义
L = 10;               % 梁的长度 (m)
x = linspace(0, L, 1000);  % 沿梁的长度分布 (m)
T = 10;               % 动画持续时间 (秒)
fps = 30;             % 帧率 (frames per second)
num_frames = T * fps; % 总帧数

% 悬臂梁的前三阶特征值 (beta_n) 和固有频率 (无量纲)
beta = [1.87510407, 4.69409113, 7.85475744];  % 悬臂梁前三阶特征值
frequencies = [3.52, 22.03, 61.70];  % 对应的前三阶固有频率 (Hz) 估计值，参考悬臂梁理论

% 定义振型函数
vibration_mode = @(beta_n, x, L) (cosh(beta_n * x / L) - cos(beta_n * x / L)) - ...
    ((cosh(beta_n) + cos(beta_n)) / (sinh(beta_n) + sin(beta_n))) * (sinh(beta_n * x / L) - sin(beta_n * x / L));

% 计算前三阶振型
mode1 = vibration_mode(beta(1), x, L);  % 第一阶振型
mode2 = vibration_mode(beta(2), x, L);  % 第二阶振型
mode3 = vibration_mode(beta(3), x, L);  % 第三阶振型

% 设置振幅和振动频率
amplitude = [0.1, 0.05, 0.02];  % 振动的幅度
omega = 2 * pi * frequencies;   % 转换为角频率 (rad/s)

% 选择塔顶和中部的位置
y_top = L;         % 顶端高度
y_mid = L * 0.5;   % 中部高度

% 初始化存储顶端和中部位置的位移
top_displacement_history = zeros(1, num_frames);
mid_displacement_history = zeros(1, num_frames);
time_history = linspace(0, T, num_frames);  % 时间向量

% 创建动画
figure;
for frame = 1:num_frames
    t = (frame - 1) / fps;  % 当前时间
    
    % 计算不同阶振型的动态响应（正弦函数模拟振动）
    y1 = amplitude(1) * mode1 * sin(omega(1) * t);  % 第一阶振型
    y2 = amplitude(2) * mode2 * sin(omega(2) * t);  % 第二阶振型
    y3 = amplitude(3) * mode3 * sin(omega(3) * t);  % 第三阶振型
    
    % 绘制前三阶振型的叠加结果
    y_total = y1 + y2 + y3;
    
    % 计算塔顶和中部位置的位移
    top_displacement = interp1(x, y_total, y_top);  % 插值计算顶端位移
    mid_displacement = interp1(x, y_total, y_mid);  % 插值计算中部位移
    
    % 存储位移历史
    top_displacement_history(frame) = top_displacement;
    mid_displacement_history(frame) = mid_displacement;
    
    % 清除之前的图像
    clf;
    
    % 子图 1：动态展示梁的振动状态
    subplot(2, 2, [1,3]);
    plot(y_total, x, 'LineWidth', 2);
    hold on;
    % 在主图中用圆圈标记塔顶和中部的位置
    plot(top_displacement, y_top, 'ro', 'MarkerSize', 8, 'LineWidth', 2);  % 红色圈标记塔顶位置
    plot(mid_displacement, y_mid, 'bo', 'MarkerSize', 8, 'LineWidth', 2);  % 蓝色圈标记中部位置
    axis([-0.4 0.4 0 L ]);  % 限定位移和梁长的显示范围
    ylabel('梁的长度 (m)');
    xlabel('位移 (m)');
    title(sprintf('悬臂梁振动动画 (t = %.2f 秒)', t));
    grid on;
    
    % 子图 2：展示塔顶和中部位置的位移随时间变化
    subplot(2, 2, 2);
    hold on;
    plot(time_history(1:frame), top_displacement_history(1:frame), 'r', 'LineWidth', 1.5);  % 顶端位移曲线
    
    xlabel('时间 (s)');
    ylabel('位移 (m)');
    title('塔顶位置的位移随时间变化');
    grid on;
    xlim([0 T]);
    ylim([-0.4 0.4]);  % 根据振幅设定范围
    
    subplot(2, 2, 4);
    hold on;
    plot(time_history(1:frame), mid_displacement_history(1:frame), 'b', 'LineWidth', 1.5);  % 中部位移曲线
    xlabel('时间 (s)');
    ylabel('位移 (m)');
    title('中部位置的位移随时间变化');
    grid on;
    xlim([0 T]);
    ylim([-0.2 0.2]);  % 根据振幅设定范围

    % 控制动画速度，使其更加流畅
    pause(1/fps);
end

% 计算塔顶和中部位置的频谱
Fs = fps;  % 采样频率
n = length(top_displacement_history);

% 频率向量
f = (0:n-1)*(Fs/n);

% 计算顶端和中部位置的频谱
top_fft = abs(fft(top_displacement_history));
mid_fft = abs(fft(mid_displacement_history));

% 绘制频谱图
figure;
subplot(2,1,1);
plot(f(1:n/2), top_fft(1:n/2), 'r');
title('塔顶位置的频谱');
xlabel('频率 (Hz)');
ylabel('幅值');
grid on;

subplot(2,1,2);
plot(f(1:n/2), mid_fft(1:n/2), 'b');
title('中部位置的频谱');
xlabel('频率 (Hz)');
ylabel('幅值');
grid on;
